def col_letter(n):
    s=''
    while n:
        n,r=divmod(n-1,26)
        s=chr(65+r)+s
    return s

def find_error_cells(value_rows, formula_rows, sheet='SHEET'):
    hits=[]
    for r in range(1,len(value_rows)+1):
        rv=value_rows[r-1]
        rf=formula_rows[r-1] if r-1<len(formula_rows) else []
        m=max(len(rv),len(rf))
        for c in range(1,m+1):
            v=rv[c-1] if c-1<len(rv) else ''
            f=rf[c-1] if c-1<len(rf) else ''
            if str(v).startswith('#'):
                hits.append((f"{sheet}!{col_letter(c)}{r}",v,f))
    return hits
